fruits = ["apple", "banana", "cherry"]

lengths = {fruit: len(fruit) for fruit in fruits}
print(lengths)

prices = {"coffee": 2.5, "tea": 1.8, "cake": 3.2}
in_cents = {item: round(price * 100) for item, price in prices.items()}
print(in_cents)

cheap = {item for item, price in prices.items() if price < 3}
print(sorted(cheap))

inverted = {length: fruit for fruit, length in lengths.items()}
print(inverted)
